import React, { useState, useEffect, useRef } from 'react';
import { OrbSmall } from '../components/Orb';

const PHASES = [
  { name: 'Andas in', seconds: 4, hint: 'Djupt in genom näsan' },
  { name: 'Håll',     seconds: 7, hint: 'Håll andan stilla' },
  { name: 'Andas ut', seconds: 8, hint: 'Sakta ut genom munnen' },
];
const TOTAL = 4;

const S = {
  page:  { background: '#EEEAE3', minHeight: '100vh' },
  inner: { padding: '56px 28px 110px', display: 'flex', flexDirection: 'column', justifyContent: 'space-between', minHeight: '100vh' },
  lbl:   { fontSize: 11, fontWeight: 600, color: 'rgba(26,42,42,0.3)', letterSpacing: '0.1em', textTransform: 'uppercase', marginBottom: 12 },
  btnPrimary: { width: '100%', padding: 18, borderRadius: 20, background: '#1A2A2A', color: '#EEEAE3', fontSize: 15, fontWeight: 600, letterSpacing: '-0.02em' },
  btnGhost:   { width: '100%', padding: 16, borderRadius: 20, background: 'rgba(26,42,42,0.07)', color: '#2D6B6B', fontSize: 15, fontWeight: 500 },
};

export default function Breathing({ setPage }) {
  const [running, setRunning] = useState(false);
  const [done,    setDone]    = useState(false);
  const [phase,   setPhase]   = useState(0);
  const [count,   setCount]   = useState(0);
  const [cycle,   setCycle]   = useState(0);
  const timer = useRef(null);

  const runPhase = (pi, ci) => {
    if (ci >= TOTAL) { setRunning(false); setDone(true); return; }
    setPhase(pi); setCycle(ci);
    const secs = PHASES[pi].seconds;
    setCount(secs);
    let c = secs;
    clearInterval(timer.current);
    timer.current = setInterval(() => {
      c--; setCount(c);
      if (c <= 0) {
        clearInterval(timer.current);
        const np = (pi + 1) % 3;
        setTimeout(() => runPhase(np, np === 0 ? ci + 1 : ci), 350);
      }
    }, 1000);
  };

  const start = () => { setRunning(true); setDone(false); runPhase(0, 0); };
  const reset = () => { clearInterval(timer.current); setRunning(false); setDone(false); setPhase(0); setCount(0); setCycle(0); };
  useEffect(() => () => clearInterval(timer.current), []);

  const cur = PHASES[phase];
  const circleSize = running ? (phase <= 1 ? 260 : 160) : 200;

  if (done) return (
    <div style={{ ...S.page, display: 'flex', flexDirection: 'column' }}>
      <div style={S.inner}>
        <OrbSmall />
        <div>
          <div style={{ fontSize: 52, fontWeight: 700, letterSpacing: '-0.05em', lineHeight: 1, color: '#1A2A2A', marginBottom: 8 }}>
            Klart<span style={{ color: '#2D6B6B' }}>.</span>
          </div>
          <p style={{ fontSize: 14, color: 'rgba(26,42,42,0.38)', marginBottom: 36 }}>Nervsystemet är återställt.</p>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
            <button onClick={() => setPage('checkin')} style={S.btnPrimary}>Check-in →</button>
            <button onClick={reset} style={S.btnGhost}>Gör om</button>
          </div>
        </div>
      </div>
    </div>
  );

  if (running) return (
    <div style={{ ...S.page, display: 'flex', flexDirection: 'column' }}>
      <div style={S.inner}>
        {/* Phase indicators */}
        <div style={{ display: 'flex', justifyContent: 'center', gap: 40 }}>
          {PHASES.map((p, i) => (
            <div key={i} style={{ textAlign: 'center' }}>
              <div style={{ fontSize: 28, fontWeight: 700, letterSpacing: '-0.04em', color: phase === i ? '#1A2A2A' : 'rgba(26,42,42,0.12)', transition: 'color 0.5s' }}>{p.seconds}</div>
              <div style={{ fontSize: 10, fontWeight: 600, color: phase === i ? '#2D6B6B' : 'rgba(26,42,42,0.18)', textTransform: 'uppercase', letterSpacing: '0.08em', marginTop: 3, transition: 'color 0.5s' }}>
                {p.name.split(' ')[0]}
              </div>
            </div>
          ))}
        </div>

        {/* Breathing circle */}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <div style={{
            width: circleSize, height: circleSize, borderRadius: '50%',
            background: 'radial-gradient(circle at 38% 35%, #7EC8C8 0%, #2D6B6B 50%, #1A3A3A 100%)',
            boxShadow: '0 0 80px rgba(45,107,107,0.25)',
            display: 'flex', alignItems: 'center', justifyContent: 'center', flexDirection: 'column',
            transition: `all ${phase === 0 ? PHASES[0].seconds : phase === 2 ? PHASES[2].seconds : 0.5}s ${phase === 1 ? 'ease' : 'linear'}`,
          }}>
            <div style={{ fontSize: 60, fontWeight: 700, letterSpacing: '-0.05em', color: 'rgba(255,255,255,0.95)', lineHeight: 1 }}>{count}</div>
            <div style={{ fontSize: 10, fontWeight: 600, color: 'rgba(255,255,255,0.5)', textTransform: 'uppercase', letterSpacing: '0.1em', marginTop: 5 }}>{cur.name}</div>
          </div>
        </div>

        {/* Hint + cycle */}
        <div>
          <div style={{ padding: '14px 20px', borderRadius: 18, background: 'rgba(255,255,255,0.5)', border: '1px solid rgba(255,255,255,0.8)', textAlign: 'center' }}>
            <p style={{ fontSize: 13, fontWeight: 500, color: 'rgba(26,42,42,0.45)' }}>{cur.hint}</p>
            <p style={{ fontSize: 11, color: 'rgba(26,42,42,0.25)', marginTop: 6, fontWeight: 500 }}>Omgång {cycle + 1} / {TOTAL}</p>
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div style={{ ...S.page, display: 'flex', flexDirection: 'column' }}>
      <div style={S.inner}>
        <div>
          <p style={S.lbl}>4 – 7 – 8</p>
          <h2 style={{ fontSize: 36, fontWeight: 700, letterSpacing: '-0.05em', lineHeight: 1.04, color: '#1A2A2A' }}>Andning.</h2>
        </div>

        {/* Idle orb */}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <div style={{ width: 220, height: 220, borderRadius: '50%', background: 'radial-gradient(circle at 38% 35%, #7EC8C8 0%, #2D6B6B 50%, #1A3A3A 100%)', boxShadow: '0 0 100px rgba(45,107,107,0.3)', animation: 'orbFloatFree 7s ease-in-out infinite', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <div style={{ width: 110, height: 110, borderRadius: '50%', background: 'rgba(255,255,255,0.12)', border: '1px solid rgba(255,255,255,0.25)' }} />
          </div>
        </div>

        <button onClick={start} style={S.btnPrimary}>Starta</button>
      </div>
    </div>
  );
}
